metadata.er-schema:
{
  "title": "Looply · 地址库管理 实体关系图",
  "version": "v1.0 · 2026-05-07",
  "tables": [
    {
      "name": "address",
      "comment": "用户地址",
      "columns": [
        {
          "name": "id",
          "comment": "主键 UUID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "user_id",
          "comment": "关联用户",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "label",
          "comment": "地址标签(Home/Office)",
          "constraint": ""
        },
        {
          "name": "country_code",
          "comment": "ISO 3166-1 国家代码",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "recipient_name",
          "comment": "收件人姓名",
          "constraint": ""
        },
        {
          "name": "phone_country",
          "comment": "电话区号(+1)",
          "constraint": ""
        },
        {
          "name": "phone_number",
          "comment": "电话号码",
          "constraint": ""
        },
        {
          "name": "address_line1",
          "comment": "地址行1(街道)",
          "constraint": ""
        },
        {
          "name": "address_line2",
          "comment": "地址行2(公寓)",
          "constraint": ""
        },
        {
          "name": "city",
          "comment": "城市",
          "constraint": ""
        },
        {
          "name": "state_province",
          "comment": "州/省",
          "constraint": ""
        },
        {
          "name": "postal_code",
          "comment": "邮政编码",
          "constraint": ""
        },
        {
          "name": "district",
          "comment": "区/町(亚洲地址)",
          "constraint": ""
        },
        {
          "name": "building_name",
          "comment": "建筑名称(日本)",
          "constraint": ""
        },
        {
          "name": "is_default",
          "comment": "是否默认地址",
          "constraint": ""
        },
        {
          "name": "address_type",
          "comment": "类型(shipping/billing/return)",
          "constraint": ""
        },
        {
          "name": "verified",
          "comment": "是否已验证",
          "constraint": ""
        },
        {
          "name": "verified_at",
          "comment": "验证时间",
          "constraint": ""
        },
        {
          "name": "latitude",
          "comment": "纬度",
          "constraint": ""
        },
        {
          "name": "longitude",
          "comment": "经度",
          "constraint": ""
        },
        {
          "name": "place_id",
          "comment": "Google Place ID",
          "constraint": "UNIQUE"
        },
        {
          "name": "raw_input",
          "comment": "用户原始输入(JSON)",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "核心实体，存储用户所有地址数据"
    },
    {
      "name": "country_config",
      "comment": "国家地址配置",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "country_code",
          "comment": "国家代码",
          "constraint": "UNIQUE"
        },
        {
          "name": "field_name",
          "comment": "字段名",
          "constraint": "UNIQUE"
        },
        {
          "name": "required",
          "comment": "是否必填",
          "constraint": ""
        },
        {
          "name": "display_order",
          "comment": "展示顺序",
          "constraint": ""
        },
        {
          "name": "display_label",
          "comment": "展示标签(多语言key)",
          "constraint": ""
        },
        {
          "name": "placeholder",
          "comment": "占位提示文案",
          "constraint": ""
        },
        {
          "name": "enabled",
          "comment": "是否启用",
          "constraint": ""
        }
      ],
      "note": "定义各国地址字段的必填/选填规则和展示顺序"
    },
    {
      "name": "validation_rule",
      "comment": "校验规则",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "country_code",
          "comment": "国家代码",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "field_name",
          "comment": "校验字段",
          "constraint": ""
        },
        {
          "name": "rule_type",
          "comment": "规则类型(regex/range/enum)",
          "constraint": ""
        },
        {
          "name": "rule_value",
          "comment": "规则值(正则表达式等)",
          "constraint": ""
        },
        {
          "name": "error_message_key",
          "comment": "错误提示(i18n key)",
          "constraint": ""
        },
        {
          "name": "priority",
          "comment": "优先级",
          "constraint": ""
        },
        {
          "name": "enabled",
          "comment": "是否启用",
          "constraint": ""
        }
      ],
      "note": "各国各字段的格式校验正则和错误提示"
    },
    {
      "name": "address_division",
      "comment": "行政区划层级",
      "columns": [
        {
          "name": "id",
          "comment": "主键 UUID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "country_code",
          "comment": "国家代码",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "parent_id",
          "comment": "父级ID(自引用)",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "level",
          "comment": "层级(1=州/省 2=市 3=区/町)",
          "constraint": ""
        },
        {
          "name": "code",
          "comment": "行政区划代码(ISO 3166-2)",
          "constraint": "UNIQUE"
        },
        {
          "name": "name",
          "comment": "官方名称(英文)",
          "constraint": ""
        },
        {
          "name": "name_local",
          "comment": "本地语言名称",
          "constraint": ""
        },
        {
          "name": "abbreviation",
          "comment": "缩写(CA/NY/TX)",
          "constraint": ""
        },
        {
          "name": "zip_prefix",
          "comment": "ZIP前缀范围(前端即时校验)",
          "constraint": ""
        },
        {
          "name": "enabled",
          "comment": "是否启用",
          "constraint": ""
        },
        {
          "name": "sort_order",
          "comment": "排序权重",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "数据更新时间",
          "constraint": ""
        }
      ],
      "note": "各国行政区划树形数据(州/市/区)，支撑下拉选择和合理性校验"
    },
    {
      "name": "postal_code_mapping",
      "comment": "邮编映射表",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "country_code",
          "comment": "国家代码",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "postal_code",
          "comment": "邮政编码",
          "constraint": "UNIQUE"
        },
        {
          "name": "city",
          "comment": "城市",
          "constraint": ""
        },
        {
          "name": "state_province",
          "comment": "州/省",
          "constraint": ""
        },
        {
          "name": "zip_range_start",
          "comment": "ZIP范围起始",
          "constraint": ""
        },
        {
          "name": "zip_range_end",
          "comment": "ZIP范围结束",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "数据更新时间",
          "constraint": ""
        }
      ],
      "note": "邮编→城市/州反查，支持合理性建议"
    },
    {
      "name": "address_audit_log",
      "comment": "地址审计日志",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "address_id",
          "comment": "地址ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "modified_by",
          "comment": "修改人ID",
          "constraint": ""
        },
        {
          "name": "modifier_type",
          "comment": "修改方类型(user/system/service)",
          "constraint": ""
        },
        {
          "name": "action",
          "comment": "操作(create/update/delete)",
          "constraint": ""
        },
        {
          "name": "changes",
          "comment": "字段变更diff(JSON)",
          "constraint": ""
        },
        {
          "name": "request_context",
          "comment": "业务上下文(工单号/订单号)",
          "constraint": ""
        },
        {
          "name": "ip_address",
          "comment": "IP地址",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "操作时间",
          "constraint": ""
        }
      ],
      "note": "记录所有地址修改操作，保留1年"
    },
    {
      "name": "user",
      "comment": "用户(外部)",
      "columns": [
        {
          "name": "id",
          "comment": "用户ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "email",
          "comment": "邮箱",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "账户状态",
          "constraint": ""
        }
      ],
      "note": "用户模块提供，地址库引用user_id"
    },
    {
      "name": "country",
      "comment": "国家(外部)",
      "columns": [
        {
          "name": "code",
          "comment": "ISO 3166-1 alpha-2",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "name",
          "comment": "国家名称",
          "constraint": ""
        },
        {
          "name": "phone_prefix",
          "comment": "电话区号",
          "constraint": ""
        },
        {
          "name": "enabled",
          "comment": "是否启用",
          "constraint": ""
        }
      ],
      "note": "MARKET模块提供，地址库引用country_code"
    }
  ],
  "relations": [
    {
      "from": "user",
      "to": "address",
      "type": "1:N",
      "label": "拥有多个地址",
      "color": "#1565C0",
      "penwidth": 1.8
    },
    {
      "from": "country",
      "to": "address",
      "type": "1:N",
      "label": "地址所属国家",
      "color": "#7B1FA2",
      "penwidth": 1.4
    },
    {
      "from": "country",
      "to": "country_config",
      "type": "1:N",
      "label": "国家字段配置",
      "color": "#7B1FA2",
      "penwidth": 1.4
    },
    {
      "from": "country",
      "to": "validation_rule",
      "type": "1:N",
      "label": "国家校验规则",
      "color": "#7B1FA2",
      "penwidth": 1.4
    },
    {
      "from": "country",
      "to": "postal_code_mapping",
      "type": "1:N",
      "label": "邮编数据",
      "color": "#7B1FA2",
      "penwidth": 1.4
    },
    {
      "from": "country",
      "to": "address_division",
      "type": "1:N",
      "label": "行政区划数据",
      "color": "#7B1FA2",
      "penwidth": 1.4
    },
    {
      "from": "address_division",
      "to": "address_division",
      "type": "1:N",
      "label": "父子层级(自引用)",
      "color": "#E8833A",
      "penwidth": 1.2,
      "style": "dashed"
    },
    {
      "from": "address",
      "to": "address_audit_log",
      "type": "1:N",
      "label": "修改记录",
      "color": "#388E3C",
      "penwidth": 1.4
    }
  ],
  "design_rules": {
    "soft_delete": "地址数据支持软删除(CCPA/GDPR要求可彻底删除)",
    "encryption": "phone_number, recipient_name 字段 AES-256 加密存储",
    "place_id_dedup": "通过 place_id 做地址去重，相似度>85%提示用户",
    "audit_retention": "审计日志保留1年，过期自动归档",
    "postal_cache": "邮编映射数据 Redis 缓存 TTL 7天，月度全量同步",
    "division_cache": "行政区划数据应用启动时加载到本地缓存，变更时热更新",
    "address_type_enum": "address_type 枚举值: shipping, billing, return",
    "modifier_type_enum": "modifier_type 枚举值: user, system, service",
    "action_enum": "action 枚举值: create, update, delete"
  }
}
